// Generated from src/registry/sources/control-ui/recipes/markdown-block.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const markdownBlockKnobs = [
  "--cui-markdown-block-radius",
  "--cui-markdown-block-background",
  "--cui-markdown-block-border-color",
  "--cui-markdown-block-border-width",
  "--cui-markdown-block-shadow",
  "--cui-markdown-block-header-border-color",
  "--cui-markdown-block-header-border-width",
  "--cui-markdown-block-icon-background",
] as const;
export type MarkdownBlockKnobStyle = Partial<Record<(typeof markdownBlockKnobs)[number], string>>;

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { createContext, useContext } from "react";
import type { MarkdownBlockKnobStyle } from "@/components/control-ui/knob-contracts/markdown-block-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { CodeCopy, type CodeCopyProps } from "@/components/control-ui/ui/code";
import { Markdown } from "@/components/control-ui/ui/markdown";
import { ScrollArea } from "@/components/control-ui/ui/scroll-area";

const MarkdownBlockContext = createContext<string | null>(null);

function useMarkdownBlockContext() {
  const code = useContext(MarkdownBlockContext);
  if (code === null) throw new Error("MarkdownBlock compound components must be rendered inside <MarkdownBlock>.");
  return code;
}

export type MarkdownBlockProps = Omit<ComponentProps<"figure">, "style"> & {
  code: string;
  style?: CSSProperties & MarkdownBlockKnobStyle;
};

export function MarkdownBlock({ code, className, children, ...props }: MarkdownBlockProps) {
  return (
    <MarkdownBlockContext.Provider value={code}>
      <figure
        data-control-ui="markdown-block"
        data-control-family="markdown-block"
        data-slot="root"
        data-surface="panel"
        className={cn("overflow-hidden", className)}
        {...props}
      >
        {children}
      </figure>
    </MarkdownBlockContext.Provider>
  );
}

export type MarkdownBlockHeaderProps = Omit<ComponentProps<"figcaption">, "style"> & {
  style?: CSSProperties & MarkdownBlockKnobStyle;
};

export function MarkdownBlockHeader({ className, ...props }: MarkdownBlockHeaderProps) {
  return (
    <figcaption
      data-control-ui="markdown-block"
      data-control-family="markdown-block"
      data-slot="header"
      className={cn("flex items-center justify-between", className)}
      {...props}
    />
  );
}

export type MarkdownBlockTitleProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & MarkdownBlockKnobStyle;
};

export function MarkdownBlockTitle({ children = "Markdown", className, ...props }: MarkdownBlockTitleProps) {
  return (
    <div
      data-control-ui="markdown-block"
      data-control-family="markdown-block"
      data-slot="title"
      className={cn("flex min-w-0 items-center", className)}
      {...props}
    >
      <span
        aria-hidden="true"
        data-control-ui="markdown-block"
        data-control-family="markdown-block"
        data-slot="title-icon"
        className="flex items-center justify-center"
      >
        MD
      </span>
      <span className="truncate" title={typeof children === "string" ? children : undefined}>
        {children}
      </span>
    </div>
  );
}

export type MarkdownBlockCopyProps = Omit<CodeCopyProps, "value">;

// IS CodeCopy, so markdown block's copy and a code block's copy can never drift
export function MarkdownBlockCopy({ "aria-label": ariaLabel = "Copy markdown", ...props }: MarkdownBlockCopyProps) {
  const code = useMarkdownBlockContext();
  return <CodeCopy value={code} aria-label={ariaLabel} {...props} />;
}

export type MarkdownBlockContentProps = ComponentProps<"div"> & {
  /** Height at which the content starts to scroll. */
  maxHeight?: string;
  style?: CSSProperties & MarkdownBlockKnobStyle;
};

export function MarkdownBlockContent({ children, className, maxHeight = "420px", ...props }: MarkdownBlockContentProps) {
  const code = useMarkdownBlockContext();

  return (
    <ScrollArea maxHeight={maxHeight}>
      <div data-control-ui="markdown-block" data-control-family="markdown-block" data-slot="content" className={className} {...props}>
        {children ?? <Markdown content={code} />}
      </div>
    </ScrollArea>
  );
}

@layer components {
  :where([data-control-family="markdown-block"][data-slot="root"]) {
    margin-block: calc(var(--spacing) * 4);
    --cui-markdown-block-radius: var(--radius-panel);
    --cui-markdown-block-background: var(--background);
    --cui-markdown-block-border-color: var(--border);
    --cui-markdown-block-border-width: var(--control-rim-width);
    --cui-markdown-block-shadow: var(--shadow-sm);
    --cui-markdown-block-header-border-color: var(--border);
    --cui-markdown-block-header-border-width: var(--control-rim-width);
    --cui-markdown-block-icon-background: oklch(from var(--foreground) l c h / 0.08);
    background: var(--cui-markdown-block-background);
    border: var(--cui-markdown-block-border-width) solid var(--cui-markdown-block-border-color);
    border-radius: var(--cui-markdown-block-radius);
    box-shadow: var(--cui-markdown-block-shadow);
  }

  :where([data-control-family="markdown-block"][data-slot="header"]) {
    gap: calc(var(--spacing) * 3);
    min-block-size: var(--control-h-lg);
    padding-inline: calc(var(--spacing) * 4) calc(var(--spacing) * 1.5);
    padding-block: calc(var(--spacing) * 1.5);
    border-block-end: var(--cui-markdown-block-header-border-width) solid var(--cui-markdown-block-header-border-color);
  }

  :where([data-control-family="markdown-block"][data-slot="title"]) {
    gap: calc(var(--spacing) * 2);
    font-size: var(--text-body);
    font-weight: var(--font-weight-semibold);
    text-wrap: balance;
  }

  :where([data-control-family="markdown-block"][data-slot="content"]) {
    padding: calc(var(--spacing) * 4);
    overflow-wrap: break-word;
  }

  :where([data-control-family="markdown-block"][data-slot="title-icon"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
    background: var(--cui-markdown-block-icon-background);
    border-radius: var(--radius-md);
    font-size: var(--text-micro);
  }
}

@property --cui-markdown-block-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-markdown-block-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-markdown-block-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-markdown-block-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-markdown-block-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-markdown-block-header-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-markdown-block-header-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-markdown-block-icon-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}
